export const MASTERY_CHOICES={arc:{economy:`Arc Bolt costs ${ABILITIES.arc.economyMp} mana.`,power:"Arc Bolt deals 15% more damage."},brace:{barrier:"Brace barrier is 15 points larger.",recovery:"Brace cooldown is 1 exchange shorter."},disrupt:{power:"Disrupt deals 15% more damage.",immunity:"Successful Disrupts shorten interrupt immunity by 1 exchange."},mend:{healing:"Mend heals 15% more.",recovery:"Mend cooldown is 1 exchange shorter."}};
// Single source for what an action spends. actionInfo (combat) and the Abilities tab both read this.
export function abilityCost(id,mastery,variant){const a=ABILITIES[id]||{};let mp=a.mp||0,sp=a.sp||0;if(id==='arc'&&mastery?.arc?.choice==='economy')mp=a.economyMp;if(variant==='wardcast')sp+=a.wardcastSp||0;if(variant==='guardstrike')sp=a.guardstrikeSp??sp;if(variant==='sidestep')sp=a.sidestepSp??sp;return {mp,sp};}
export function costLabel({mp,sp}){return mp&&sp?`${mp} mana · ${sp} stamina`:mp?`${mp} mana`:sp?`${sp} stamina`:'Free';}
